import re,os
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
I=G['Demo pair 1 input']; O=G['Demo pair 1 output']
def objs(g):
    seen=set(); res=[]
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v and (i,j) not in seen:
                col=v; stack=[(i,j)]; cells=[]
                while stack:
                    a,b=stack.pop()
                    if (a,b) in seen or g[a][b]!=col: continue
                    seen.add((a,b)); cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<len(g) and 0<=y<len(g[0]): stack.append((x,y))
                res.append((col,cells))
    return res
for c,cells in objs(I):
    rs=[r for r,_ in cells]; cs=[c2 for _,c2 in cells]
    print('IN',c,sorted(cells),'h',max(rs)-min(rs)+1,'w',max(cs)-min(cs)+1)
print()
for c,cells in objs(O):
