def comps(g):
    seen=set(); res=[]
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v and (i,j) not in seen:
                col=v; stack=[(i,j)]; cells=[]
                while stack:
                    a,b=stack.pop()
                    if (a,b) in seen or g[a][b]!=col: continue
                    seen.add((a,b)); cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<len(g) and 0<=y<len(g[0]): stack.append((x,y))
                res.append((col,cells))
    return res

def transform(g):
    h,w=len(g),len(g[0])
    out=[[0]*w for _ in range(h)]
    objs=comps(g)
    # order: rightmost original column, descending
    objs.sort(key=lambda o:-max(c for _,c in o[1]))
    for col,cells in objs:
        shift=0
        while True:
            ns=[(a,b+shift+1) for a,b in cells]
            if any(b>=w or out[a][b] for a,b in ns): break
            shift+=1
        for a,b in cells: out[a][b+shift]=col
    return out

assert transform(I)==O, [r for r,r2 in zip(transform(I),O) if r!=r2]
print("demo OK")
